initial_condition:
with {
   the SUT containing an initial state
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Delete Temporal Representation Of Entity With Returning Response with Response Status Code set to 405     and
        Delete Temporal Representation Of Entity With Returning Response with Response Body containing the type '${EMPTY}'     and
        Delete Temporal Representation Of Entity With Returning Response with Response body containing 'title' element
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/temporal/entities/{temporal_entity_representation_id}'
        method set to 'DELETE'
        Delete Temporal Representation Of Entity With Returning Response with id set to '${EMPTY}'
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Delete Temporal Representation Of Entity With Returning Response with Response Status Code set to 400     and
        Delete Temporal Representation Of Entity With Returning Response with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/BadRequestData'     and
        Delete Temporal Representation Of Entity With Returning Response with Response body containing 'title' element
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/temporal/entities/{temporal_entity_representation_id}'
        method set to 'DELETE'
        Delete Temporal Representation Of Entity With Returning Response with id set to 'invalidId'
}
